import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/**
 * figma: ButtonGroupButton (144 variants) + ButtonGroupIconButton (168).
 *
 * In Figma the corner treatment is an explicit `Position` property
 * (Left | Middle | Right | Single, plus Top | Bottom for the icon set when the
 * group is vertical). In code we get the same result declaratively from the
 * child's index, so `ButtonGroup` owns the rounding and the shared border and
 * the children stay plain `Button` / `IconButton`.
 *
 * Restricted to the variants the Figma set ships: outline | secondary | ghost.
 */
const buttonGroupVariants = cva(
  "flex w-fit items-stretch [&>*]:focus-visible:z-10 [&>*]:focus-visible:relative",
  {
    variants: {
      orientation: {
        horizontal: cn(
          "flex-row",
          "[&>*:not(:first-child)]:rounded-s-none [&>*:not(:last-child)]:rounded-e-none",
          "[&>*:not(:first-child)]:-ms-px"
        ),
        vertical: cn(
          "flex-col",
          "[&>*:not(:first-child)]:rounded-t-none [&>*:not(:last-child)]:rounded-b-none",
          "[&>*:not(:first-child)]:-mt-px"
        ),
      },
    },
    defaultVariants: { orientation: "horizontal" },
  }
);

function ButtonGroup({
  className,
  orientation,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof buttonGroupVariants>) {
  return (
    <div
      role="group"
      data-slot="button-group"
      data-orientation={orientation ?? "horizontal"}
      className={cn(buttonGroupVariants({ orientation }), className)}
      {...props}
    />
  );
}

/** A non-interactive label or addon rendered inline with the group. */
function ButtonGroupText({
  className,
  asChild = false,
  ...props
}: React.ComponentProps<"div"> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : "div";
  return (
    <Comp
      data-slot="button-group-text"
      className={cn(
        "flex items-center gap-1 rounded-lg border bg-muted px-2.5 text-sm font-medium",
        "[&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    />
  );
}

function ButtonGroupSeparator({
  className,
  orientation = "vertical",
  ...props
}: React.ComponentProps<"div"> & { orientation?: "horizontal" | "vertical" }) {
  return (
    <div
      data-slot="button-group-separator"
      role="separator"
      aria-orientation={orientation}
      className={cn(
        "self-stretch bg-border",
        orientation === "vertical" ? "w-px" : "h-px w-full",
        className
      )}
      {...props}
    />
  );
}

export { ButtonGroup, ButtonGroupText, ButtonGroupSeparator, buttonGroupVariants };
